function icons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[el.dataset.icon]||paths.sparkles}"/></svg>`)}
const flowers=[{id:'sakura',name:'樱花',en:'Cherry blossom',role:'轻盈的花枝',height:53},{id:'calla',name:'马蹄莲',en:'Calla lily',role:'干净的主花',height:49},{id:'chrysanthemum',name:'秋菊',en:'Chrysanthemum',role:'温暖的色彩',height:35},{id:'pine',name:'松枝',en:'Pine branch',role:'有力量的线条',height:57},{id:'maple',name:'红枫',en:'Japanese maple',role:'舒展的枝叶',height:45},{id:'pampas',name:'蒲苇',en:'Pampas grass',role:'柔软的空气感',height:58}];
const vessels=[{id:'round',name:'窑变圆瓶',en:'Bronze round vase',height:23},{id:'bottle',name:'褐釉长颈瓶',en:'Brown bottle vase',height:29}];
const anchors={sakura:.469,calla:.259,chrysanthemum:.531,pine:.443,maple:.534,pampas:.404};
const allAssets=[...flowers,...vessels];const assetById=Object.fromEntries(allAssets.map(a=>[a.id,a]));
const scenes={paper:['#f8f5ec','#e2ddd0','温暖的米灰色石灰墙与浅色石台'],stone:['#e2e6e2','#aeb9b2','青灰色墙面与自然石台'],night:['#566259','#27312b','深墨绿色背景与沉静的暗调光影']};
const STORE='hanama-draft-v1';const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const initial=()=>({version:1,id:uid(),title:'风经过的地方',vessel:'round',scene:'paper',mood:'静寂',intention:'像清晨的风掠过庭院，安静、自然，留一点不完美。',items:[{id:uid(),type:'pine',x:50,y:65,h:48,angle:-22,trim:0,flip:false},{id:uid(),type:'calla',x:50,y:65,h:39,angle:8,trim:0,flip:false},{id:uid(),type:'chrysanthemum',x:50,y:65,h:26,angle:32,trim:0,flip:false}]});
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));const clone=o=>JSON.parse(JSON.stringify(o));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(v){if(!v||v.version!==1||!Array.isArray(v.items)||v.items.length>24||!vessels.some(a=>a.id===v.vessel)||!Object.hasOwn(scenes,v.scene))throw Error('这不是有效的花间草稿');let base=initial();return {...base,id:typeof v.id==='string'?v.id.slice(0,80):uid(),title:String(v.title||'未命名作品').slice(0,40),vessel:v.vessel,scene:v.scene,mood:['静寂','侘寂','春意','野趣'].includes(v.mood)?v.mood:'静寂',intention:String(v.intention||'').slice(0,600),items:v.items.map(i=>{if(!flowers.some(a=>a.id===i.type)||!['x','y','h','angle','trim'].every(k=>Number.isFinite(i[k])))throw Error('花材信息不完整');return {id:uid(),type:i.type,x:clamp(i.x,5,95),y:clamp(i.y,15,92),h:clamp(i.h,15,70),angle:clamp(i.angle,-85,85),trim:clamp(i.trim,0,35),flip:!!i.flip}})}}
let state=initial(),selected=null,category='flowers',undoStack=[],redoStack=[],toastTimer,images={},galleryUrls=[],importArtFor=null,drag=null;
try{const v=localStorage.getItem(STORE);if(v)state=validate(JSON.parse(v))}catch{}
let sharedLoaded=false;try{if(location.hash.startsWith('#draft=')){const data=location.hash.slice(7);if(data.length>22000)throw Error();state=validate(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(data),c=>c.charCodeAt(0)))));state.id=uid();sharedLoaded=true;history.replaceState(null,'',location.pathname+location.search)}}catch{setTimeout(()=>toast('草稿链接不完整，请重新复制。'),500)}
selected=state.items.at(-1)?.id||null;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));$('#save-state').textContent='已自动保存到本机'}catch{$('#save-state').textContent='本机保存不可用，请导出草稿'}}
function checkpoint(){undoStack.push(clone(state));if(undoStack.length>60)undoStack.shift();redoStack=[];renderHistory()}
function renderHistory(){$('#undo-button').disabled=!undoStack.length;$('#redo-button').disabled=!redoStack.length}
function current(){return state.items.find(i=>i.id===selected)}
function stemStyle(i){const img=images[i.type];const ratio=img?img.naturalWidth/img.naturalHeight:.4;const height=i.h*(1-i.trim/100);return `left:${i.x}%;top:${i.y}%;height:${height}%;width:${i.h*ratio}%;transform-origin:${anchors[i.type]*100}% 100%;transform:translate(${-anchors[i.type]*100}%,-100%) rotate(${i.angle}deg) scaleX(${i.flip?-1:1});`}
function renderStage(){const root=$('#composition');root.innerHTML=state.items.map(i=>`<div class="stem ${i.id===selected?'selected':''}" data-id="${i.id}" style="${stemStyle(i)}" role="button" tabindex="0" aria-label="${assetById[i.type].name}，点击选择，拖动调整" aria-pressed="${i.id===selected}"><div style="height:100%;overflow:hidden"><img src="/assets/${i.type}.png" alt="" draggable="false" style="height:${100/(1-i.trim/100)}%"></div></div>`).join('');$('#vessel').src=`/assets/${state.vessel}.png`;$('#vessel').alt=assetById[state.vessel].name;$('#vessel').style.height=assetById[state.vessel].height+'%';$('#stage').dataset.scene=state.scene;$$('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===state.scene));$('#study-count').textContent=String(state.items.length).padStart(3,'0');renderSelection();renderHistory()}
function renderSelection(){let i=current();$('#selected-empty').hidden=!!i;$('#selection-controls').hidden=!i;if(!i)return;$('#selected-thumb').src=`/assets/${i.type}.png`;$('#selected-thumb').alt=assetById[i.type].name;$('#selected-name').textContent=assetById[i.type].name;$('#angle').value=i.angle;$('#size').value=i.h;$('#trim').value=i.trim;$('#angle-value').value=i.angle+'°';$('#size-value').value=Math.round(i.h/assetById[i.type].height*100)+'%';$('#trim-value').value=i.trim+'%'}
function renderAll(){renderStage();$('#work-title').value=state.title;$('#intention').value=state.intention;$$('[data-mood]').forEach(b=>b.classList.toggle('active',b.dataset.mood===state.mood));persist()}
function renderMaterials(){$$('#material-grid button').forEach(b=>b.remove());const materials=category==='flowers'?flowers:vessels;$('#material-grid').innerHTML=materials.map(a=>`<button class="material-card" data-material="${a.id}" aria-label="${category==='flowers'?'添加':'选择'}${a.name}"><span class="add-mark">${category==='flowers'?'+':''}</span><img src="/assets/${a.id}.png" alt="${a.name}" draggable="false"><strong>${a.name}</strong><small>${a.role||'手作质感花器'}</small></button>`).join('');$('#material-grid').onclick=e=>{const b=e.target.closest('[data-material]');if(!b)return;const type=b.dataset.material;if(category==='vessels'){checkpoint();const dy=assetById[state.vessel].height-assetById[type].height;state.items.forEach(i=>i.y=clamp(i.y+dy,15,92));state.vessel=type;renderStage();persist();toast(`已换成${assetById[type].name}`);return}if(state.items.length>=24)return toast('先让这 24 枝找到自己的位置，再添加新花材。');checkpoint();const item={id:uid(),type,x:50,y:89-assetById[state.vessel].height,h:Math.round(assetById[type].height*.82),angle:Math.round(Math.random()*30-15),trim:0,flip:false};state.items.push(item);selected=item.id;renderStage();persist();toast(`添入一枝${assetById[type].name}`)}}
$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));renderMaterials()});
$('#composition').addEventListener('pointerdown',e=>{if(e.button!==0)return;const el=e.target.closest('.stem');if(!el)return;e.preventDefault();selected=el.dataset.id;const item=current();checkpoint();drag={pointer:e.pointerId,item,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y,rect:$('#stage').getBoundingClientRect(),el};$$('.stem').forEach(n=>{n.classList.toggle('selected',n===el);n.setAttribute('aria-pressed',String(n===el))});renderSelection();el.focus({preventScroll:true});el.setPointerCapture(e.pointerId)});
$('#composition').addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;drag.item.x=clamp(drag.x+(e.clientX-drag.startX)/drag.rect.width*100,5,95);drag.item.y=clamp(drag.y+(e.clientY-drag.startY)/drag.rect.height*100,15,92);drag.el.style.cssText=stemStyle(drag.item)});
function finishDrag(e){if(!drag||drag.pointer!==e.pointerId)return;drag=null;persist()}
$('#composition').addEventListener('pointerup',finishDrag);$('#composition').addEventListener('pointercancel',finishDrag);
$('#composition').addEventListener('click',e=>{const stem=e.target.closest('.stem');if(stem){selected=stem.dataset.id;renderSelection()}});
$('#stage').addEventListener('keydown',e=>{if(e.target.closest('input,textarea'))return;let item=current();if(e.key==='Enter'&&e.target.closest('.stem')){selected=e.target.closest('.stem').dataset.id;renderStage();return}if(!item)return;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeSelected();return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();checkpoint();const step=e.shiftKey?2:.5;item.x=clamp(item.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),5,95);item.y=clamp(item.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0),15,92);const el=$(`.stem[data-id="${item.id}"]`);if(el)el.style.cssText=stemStyle(item);persist()});
for(const [id,key] of [['angle','angle'],['size','h'],['trim','trim']]){let active=false;const el=$('#'+id);el.addEventListener('input',()=>{const item=current();if(!item)return;if(!active){checkpoint();active=true}item[key]=+el.value;renderStage();persist()});el.addEventListener('change',()=>active=false);el.addEventListener('blur',()=>active=false)}
function removeSelected(){if(!current())return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);selected=state.items.at(-1)?.id||null;renderStage();persist()}
$('#delete-button').onclick=removeSelected;$('#flip-button').onclick=()=>{if(!current())return;checkpoint();current().flip=!current().flip;renderStage();persist()};$('#layer-button').onclick=()=>{let item=current();if(!item)return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);state.items.push(item);renderStage();persist()};
$('#undo-button').onclick=()=>{if(!undoStack.length)return;redoStack.push(clone(state));state=undoStack.pop();selected=state.items.at(-1)?.id||null;renderAll()};$('#redo-button').onclick=()=>{if(!redoStack.length)return;undoStack.push(clone(state));state=redoStack.pop();selected=state.items.at(-1)?.id||null;renderAll()};
$('#guide-button').onclick=()=>{const on=$('#guide').hidden;$('#guide').hidden=!on;$('#guide-button').setAttribute('aria-pressed',String(on))};$('#reset-button').onclick=()=>{checkpoint();state.items=[];selected=null;renderStage();persist();toast('花器已留空，随时可以撤销。')};
$$('[data-scene]').forEach(b=>b.onclick=()=>{checkpoint();state.scene=b.dataset.scene;renderStage();persist()});$$('[data-mood]').forEach(b=>b.onclick=()=>{checkpoint();state.mood=b.dataset.mood;$$('[data-mood]').forEach(t=>t.classList.toggle('active',t===b));persist()});
$('#work-title').addEventListener('input',e=>{state.title=e.target.value;persist()});$('#intention').addEventListener('input',e=>{state.intention=e.target.value;persist()});
function openModal(html,kicker='HANAMA ATELIER'){$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;icons($('#modal'));if(!$('#modal').open)$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function help(){openModal(`<h2>给自己一刻，慢慢插花。</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>选花，落枝。</strong><br>点选左侧花材和花器。拖动枝条，用角度、大小和修剪，找到喜欢的姿态。</p></div><div><span class="step-number">02</span><p><strong>写下你的意境。</strong><br>选择光与景，留下一句话。下载创作包，在 ChatGPT 的图片创作或 GPT Image 中上传 draft.png，再粘贴 prompt.txt。</p></div><div><span class="step-number">03</span><p><strong>从草稿，到作品。</strong><br>把生成的图片导入「我的作品」，下载分享卡或使用设备分享。网页本身不直接调用付费生成服务。</p></div></div><p class="file-note">键盘也能创作：选中枝条后，方向键微调，Shift + 方向键大幅移动，Delete 删除。草稿与成品保存在当前浏览器，导出文件可以备份。</p><div class="modal-actions"><button class="button dark" id="help-done">开始这一枝</button><button class="button outline" id="help-import">导入草稿文件</button></div>`);$('#help-done').onclick=()=>$('#modal').close();$('#help-import').onclick=()=>$('#draft-upload').click()}
$('#help-button').onclick=help;
function sources(){openModal(`<h2>从自然取材，从花道取意。</h2><p>花间以自由创作练习为出发点，不为作品打分，也不将简化的构图方法当作流派规范。</p><h3>花道参考</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">池坊 · 花道的三种样式 ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">草月 · 自由表达与学习 ↗</a></div><p>池坊的自由花重视草木的形状与质感；草月鼓励创作者表达自己的想法。这里的留白、方向和疏密提示，是游戏中的创作建议。</p><h3>素材说明</h3><p>六种花枝使用 GPT Image 原创生成，植物为艺术化素材，不作为植物识别依据。两只花器来自 <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>，来源页标注 CC0，已拆分裁切。灵感摄影为 Rémi Jouan 的 <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>，依据 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> 使用，已缩小尺寸，未修改内容。</p><p class="file-note">资料整理：2026 年 9 月。你的作品由你导出和分享；本工房不自动公开上传图片。</p>`,'REFERENCES & MATERIALS')}
$('#sources-button').onclick=sources;
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('图片暂时无法载入，请稍后重试'));img.src=src})}
const assetsReady=Promise.all(allAssets.map(async a=>{images[a.id]=await loadImage(`/assets/${a.id}.png`)}));
assetsReady.then(()=>renderStage()).catch(()=>toast('部分花材未载入，请刷新后重试。'));
function drawCover(ctx,img,x,y,w,h){const factor=Math.max(w/img.width,h/img.height),iw=img.width*factor,ih=img.height*factor;ctx.drawImage(img,x+(w-iw)/2,y+(h-ih)/2,iw,ih)}
async function draftCanvas(s=state,size=1600){await assetsReady;const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');const colors=scenes[s.scene];const grad=ctx.createRadialGradient(size*.28,size*.22,0,size*.4,size*.4,size*.8);grad.addColorStop(0,colors[0]);grad.addColorStop(1,colors[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,size,size);ctx.fillStyle=s.scene==='night'?'#11191018':'#aaa69312';ctx.fillRect(0,size*.8,size,size*.2);for(const i of s.items){const img=images[i.type],h=i.h/100*size,w=h*img.naturalWidth/img.naturalHeight,cut=1-i.trim/100;ctx.save();ctx.translate(i.x/100*size,i.y/100*size);ctx.rotate(i.angle*Math.PI/180);ctx.scale(i.flip?-1:1,1);ctx.drawImage(img,0,0,img.naturalWidth,img.naturalHeight*cut,-w*anchors[i.type],-h*cut,w,h*cut);ctx.restore()}const v=images[s.vessel],vh=assetById[s.vessel].height/100*size,vw=vh*v.naturalWidth/v.naturalHeight;ctx.save();ctx.shadowColor='#37312225';ctx.shadowBlur=size*.014;ctx.shadowOffsetX=size*.012;ctx.shadowOffsetY=size*.014;ctx.drawImage(v,(size-vw)/2,size*.86-vh,vw,vh);ctx.restore();return c}
const canvasBlob=(c,type='image/png',quality=.95)=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('无法导出图片，请重试')),type,quality));
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const fileTitle=s=>(s.title||'花间作品').replace(/[\\/:*?"<>|]/g,'-');
function promptFor(s=state){const list=s.items.map((i,n)=>`${n+1}. ${assetById[i.type].name} (${assetById[i.type].en}): base at (${i.x.toFixed(1)}%, ${i.y.toFixed(1)}%) from top-left, height ${(i.h*(1-i.trim/100)).toFixed(1)}% of image, rotation ${i.angle} degrees clockwise, ${i.flip?'mirrored':'original direction'}, cropped ${i.trim}% at stem base.`).join('\n');return `Use the attached draft.png as the composition reference, not merely a mood reference. Transform my handmade botanical collage into a professional, photorealistic Japanese-inspired contemporary ikebana artwork.\n\nWORK TITLE: ${s.title||'Untitled'}\nCREATIVE DIRECTION: ${s.mood}. ${s.intention}\n\nPRESERVE MY DESIGN:\nKeep the visible species, approximate flower counts, stem directions, relative heights, asymmetry, negative space, and vessel placement from the draft. Preserve the main silhouettes and the relationship between branches. Do not replace the design with a generic bouquet. Resolve collage seams and physically connect all stems naturally inside the vessel. Rendering may refine minor natural details while retaining my composition.\n\nVESSEL: ${assetById[s.vessel].name} (${assetById[s.vessel].en}). Preserve its form, color and position.\nBOTANICAL LAYOUT (ordered back to front):\n${list||'No botanical stems present.'}\n\nSCENE: ${scenes[s.scene][2]}. Soft directional window light from the upper left, physically plausible gentle shadows, subtle handmade ceramic texture, realistic botanical details, restrained palette. Photograph at arrangement eye level with slight view into the vessel, gallery-quality editorial still-life photography. Keep ample breathing room and a 1:1 composition matching the reference.\n\nAVOID: added flowers or unrelated props, dense commercial bouquets, dramatic color substitutions, impossible floating stems, distorted petals, artificial plastic textures, illustration or 3D-render look, frames, text, labels, watermarks and UI controls.\n\nThe draft is the structural source of truth. The written direction refines atmosphere, not structure.`}
function crc32(data){let c=0xffffffff;for(const v of data){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
async function zipFiles(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;for(const [name,blob] of files){const data=new Uint8Array(await blob.arrayBuffer()),filename=enc.encode(name),crc=crc32(data),local=new Uint8Array(30+filename.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x0800,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,filename.length,true);local.set(filename,30);parts.push(local,data);const cd=new Uint8Array(46+filename.length),dv=new DataView(cd.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x0800,true);dv.setUint32(16,crc,true);dv.setUint32(20,data.length,true);dv.setUint32(24,data.length,true);dv.setUint16(28,filename.length,true);dv.setUint32(42,offset,true);cd.set(filename,46);central.push(cd);offset+=local.length+data.length}const length=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,length,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制')}catch{const ta=document.createElement('textarea');ta.value=text;$('#modal').open?$('#modal-content').append(ta):document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'已复制':'请长按或选中文字后手动复制')}}
async function generatePackage(){if(!state.items.length){toast('先添入一枝花，再让灵感开花。');return}const snapshot=clone(state);openModal(`<h2>把这一刻，交给光影。</h2><p>先保存创作包，再把草稿图与 Prompt 一起交给 GPT Image。生成完成后，把图片带回花间。</p><div class="export-preview"><img id="draft-preview" alt="当前作品草稿"><div><strong>${esc(snapshot.title||'未命名作品')}</strong><p>${snapshot.items.length} 枝花材 · ${esc(assetById[snapshot.vessel].name)}<br>意境：${esc(snapshot.mood)}</p><p class="file-note">草稿决定构图，Prompt 完善质感。<br>本页面不直接调用图片生成服务。</p></div></div><label for="prompt-text" class="slider-label">为你的构图准备的 Prompt</label><textarea id="prompt-text" class="prompt-area" readonly></textarea><div class="modal-actions"><button class="button accent" id="download-package" disabled><span data-icon="download"></span>下载创作包 .zip</button><button class="button outline" id="copy-prompt" disabled><span data-icon="copy"></span>复制 Prompt</button><button class="button outline" id="import-result" disabled><span data-icon="upload"></span>导入生成作品</button></div><p class="file-note">导入图片仅保存至当前浏览器，最长边压缩至 2000 像素。解压后上传 draft.png，粘贴 prompt.txt；composition.json 可重新导入继续创作。</p>`,'DRAFT → GPT IMAGE → ARTWORK');$('#prompt-text').value=promptFor(snapshot);const c=await draftCanvas(snapshot);$('#draft-preview').src=c.toDataURL('image/jpeg',.85);['download-package','copy-prompt','import-result'].forEach(id=>$('#'+id).disabled=false);$('#copy-prompt').onclick=()=>copyText(promptFor(snapshot));$('#download-package').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const zip=await zipFiles([['draft.png',await canvasBlob(c)],['prompt.txt',new Blob([promptFor(snapshot)],{type:'text/plain;charset=utf-8'})],['composition.json',new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})],['readme.txt',new Blob(['花间 · 创作包\n\n1. 在 ChatGPT 图片创作或 GPT Image 中上传 draft.png。\n2. 粘贴 prompt.txt 全文，提交生成。\n3. 下载生成图片，在花间「我的作品」导入，保存或分享。\n4. composition.json 可以在「怎么玩 → 导入草稿文件」恢复编辑。\n\n草稿由你亲手设计；生成结果请自行检查是否保留了你的构图。\n网页版不直接调用生成 API；文件包不含任何密钥。'],{type:'text/plain;charset=utf-8'})]]);download(zip,fileTitle(snapshot)+'-创作包.zip');toast('创作包已下载，解压后即可使用。')}catch(err){toast(err.message)}finally{b.disabled=false}};$('#import-result').onclick=()=>{importArtFor=snapshot;$('#art-upload').click()}}
$('#generate-button').onclick=()=>generatePackage().catch(e=>toast(e.message));$('#export-draft').onclick=async()=>{try{download(await canvasBlob(await draftCanvas()),fileTitle(state)+'-草稿.png');toast('草稿图已下载')}catch(e){toast(e.message)}};
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('hanama-artworks',1);req.onupgradeneeded=()=>req.result.createObjectStore('works',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});dbPromise.catch(()=>{});
async function dbAction(mode,fn){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('works',mode);const req=fn(tx.objectStore('works'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('本机存储空间不足或不可用，请导出文件保存。'));tx.onabort=()=>reject(Error('保存未完成，请导出文件备份。'))})}
const listWorks=()=>dbAction('readonly',store=>store.getAll());
async function refreshCount(){try{$('#gallery-count').textContent=(await listWorks()).length}catch{}}
async function saveDraft(s=state){const snapshot=clone(s),preview=await canvasBlob(await draftCanvas(snapshot,600),'image/jpeg',.86);const prev=await dbAction('readonly',store=>store.get(snapshot.id));await dbAction('readwrite',store=>store.put({id:snapshot.id,state:snapshot,title:snapshot.title||'未命名作品',updated:Date.now(),preview,art:prev?.art||null}));await refreshCount();toast('草稿已收进「我的作品」');return snapshot.id}
$('#save-button').onclick=async e=>{e.currentTarget.disabled=true;try{await saveDraft()}catch(err){toast(err.message)}finally{$('#save-button').disabled=false}};
function setView(view){$$('.view').forEach(el=>el.hidden=el.id!==`${view}-view`);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='gallery')renderGallery().catch(err=>toast(err.message));if(view==='inspiration')renderInspiration();window.scrollTo({top:0,behavior:'instant'})}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function renderInspiration(){$('#inspiration-view').innerHTML=`<div class="page-heading"><div><p class="eyebrow">A NOTE ON IKEBANA</p><h1>花不语，自有声。</h1><p>先观察一枝的姿态，再决定另一枝的位置。</p></div><button class="text-button" id="inspiration-sources">花道与素材参考 ↗</button></div><div class="inspiration-feature"><img src="/assets/ikebana-reference.jpg" alt="2019 巴黎国际插花展中的作品，枝条与花朵在竹篮中舒展"><div class="inspiration-copy"><p class="eyebrow">STUDY 01 / 观察线条</p><h2>让一枝向远处，<br>让一朵留在此刻。</h2><p>观察枝条如何向上、横向与低处伸展，花朵又如何回应。试着用松枝定下方向，再为它添上自己的想法。</p><div class="principles"><div><b>一</b><section><h3>先看线条</h3><p>选一枝主角，试着让它稍稍偏离中心。</p></section></div><div><b>二</b><section><h3>保留呼吸</h3><p>在花与叶之间，留出能看见背景的空隙。</p></section></div><div><b>三</b><section><h3>回应花器</h3><p>让枝条的方向、质感与花器彼此呼应。</p></section></div></div><button class="button dark" id="try-study">从一枝松开始 <span>↗</span></button><p class="file-note" style="margin-top:16px">摄影：<a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Rémi Jouan / 巴黎国际插花展，2019</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> · 已缩小尺寸</p></div></div>`;$('#inspiration-sources').onclick=sources;$('#try-study').onclick=()=>{checkpoint();state=initial();state.items=state.items.filter(i=>i.type==='pine');selected=state.items[0].id;renderAll();setView('studio');toast('松枝已备好，试试你的构图。')}}
async function renderGallery(){const works=(await listWorks()).sort((a,b)=>b.updated-a.updated);galleryUrls.forEach(URL.revokeObjectURL);galleryUrls=[];$('#gallery-view').innerHTML=`<div class="page-heading"><div><p class="eyebrow">YOUR PERSONAL COLLECTION</p><h1>一花一记</h1><p>这里珍藏你的草稿与成品，仅保存在当前浏览器。</p></div><button class="button outline" id="gallery-import"><span data-icon="upload"></span>导入生成作品</button></div>${works.length?'<div class="gallery-grid">'+works.map(w=>{const url=URL.createObjectURL(w.art||w.preview);galleryUrls.push(url);return `<article class="art-card"><img src="${url}" alt="${esc(w.title)}" loading="lazy"><div class="art-card-content"><h2>${esc(w.title)}</h2><p>${w.art?'生成成品':'插花草稿'} · ${new Date(w.updated).toLocaleDateString('zh-CN')}</p><div class="art-card-actions"><button data-work-edit="${esc(w.id)}">继续创作</button><button data-work-share="${esc(w.id)}">分享作品 ↗</button><button data-work-delete="${esc(w.id)}" aria-label="删除${esc(w.title)}">删除</button></div></div></article>`}).join('')+'</div>':`<div class="empty-gallery"><h2>留住你的第一枝。</h2><p>在工房保存草稿，或把生成的成品导入这里。</p><button class="button dark" id="back-studio">回到插花台</button></div>`}`;icons($('#gallery-view'));$('#gallery-import').onclick=()=>{importArtFor=clone(state);$('#art-upload').click()};$('#back-studio')?.addEventListener('click',()=>setView('studio'));$$('[data-work-edit]').forEach(b=>b.onclick=()=>{checkpoint();const w=works.find(w=>w.id===b.dataset.workEdit);state=validate(w.state);selected=state.items.at(-1)?.id;renderAll();setView('studio')});$$('[data-work-share]').forEach(b=>b.onclick=()=>shareWork(works.find(w=>w.id===b.dataset.workShare)).catch(err=>toast(err.message)));$$('[data-work-delete]').forEach(b=>b.onclick=()=>{const w=works.find(w=>w.id===b.dataset.workDelete);openModal(`<h2>移除「${esc(w.title)}」？</h2><p>这会删除本机作品集中的草稿和成品，已下载的图片仍然保留。</p><div class="modal-actions"><button class="button outline" id="cancel-delete">保留作品</button><button class="button accent" id="confirm-delete">删除作品</button></div>`);$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=async()=>{try{await dbAction('readwrite',store=>store.delete(w.id));$('#modal').close();await renderGallery();await refreshCount();toast('已移除作品')}catch(e){toast(e.message)}}})}
async function artPoster(w){const c=document.createElement('canvas');c.width=1600;c.height=1870;const ctx=c.getContext('2d');ctx.fillStyle='#f5f2e8';ctx.fillRect(0,0,c.width,c.height);const source=w.art||await canvasBlob(await draftCanvas(w.state,1600));const url=URL.createObjectURL(source);try{const img=await loadImage(url);const fit=Math.min(1480/img.width,1480/img.height);const iw=img.width*fit,ih=img.height*fit;ctx.drawImage(img,60+(1480-iw)/2,60+(1480-ih)/2,iw,ih)}finally{URL.revokeObjectURL(url)}ctx.fillStyle='#354034';ctx.font='48px "Noto Serif SC", "Songti SC", serif';const title=w.title||'未命名作品';let label=title;while(ctx.measureText(label).width>1300)label=label.slice(0,-1);if(label!==title)label+='…';ctx.fillText(label,85,1640);ctx.fillStyle='#7a8074';ctx.font='22px sans-serif';ctx.fillText(`${w.state.mood}  /  ${w.art?'由手作草稿延展的生成作品':'亲手设计的插花草稿'}`,87,1695);ctx.fillStyle='#a5533e';ctx.font='38px "Songti SC", serif';ctx.fillText('花间',85,1790);ctx.fillStyle='#8e9286';ctx.font='16px sans-serif';ctx.fillText('HANAMA · A MOMENT WITH FLOWERS',200,1787);return canvasBlob(c)}
async function shareWork(w){openModal(`<h2>让这一枝，遇见别人。</h2><p>分享卡保留作品与题名。草稿文件还能让朋友继续你的创作。</p><div class="modal-actions"><button class="button accent" id="share-system" disabled><span data-icon="share"></span>分享图片</button><button class="button outline" id="share-download" disabled><span data-icon="download"></span>下载分享卡</button><button class="button outline" id="share-original">下载${w.art?'保存的成品':'草稿图'}</button></div><h3>也可以分享可编辑的草稿</h3><p class="file-note">链接仅携带花材布局与意境，不包含成品图片。接收者需要有权访问此工房。</p><input class="share-field" id="share-link" readonly aria-label="草稿分享链接"><div class="modal-actions"><button class="button outline" id="copy-link">复制草稿链接</button><button class="button outline" id="share-json">下载草稿文件</button></div>`,'SHARE YOUR LITTLE WORLD');const shared=clone(w.state);shared.id='shared';const data=btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(shared))));$('#share-link').value=location.origin+location.pathname+'#draft='+data;$('#copy-link').onclick=()=>copyText($('#share-link').value);$('#share-json').onclick=()=>download(new Blob([JSON.stringify(w.state,null,2)],{type:'application/json'}),fileTitle(w.state)+'.json');$('#share-original').onclick=async()=>{try{const source=w.art||await canvasBlob(await draftCanvas(w.state,1600));download(source,fileTitle(w.state)+(w.art?'-成品':'-草稿')+'.'+(source.type==='image/png'?'png':'jpg'))}catch(e){toast(e.message)}};const poster=await artPoster(w);$('#share-system').disabled=false;$('#share-download').disabled=false;$('#share-download').onclick=()=>download(poster,fileTitle(w.state)+'-分享卡.png');$('#share-system').onclick=async()=>{const file=new File([poster],fileTitle(w.state)+'.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:w.title})}else{download(poster,file.name);toast('分享卡已下载，可以发送给朋友。')}}catch(err){if(err.name!=='AbortError')toast('设备分享不可用，请下载分享卡。')}}}
$('#art-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024)return toast('请选择不超过 15 MB 的 PNG、JPG 或 WebP 图片。');const s=clone(importArtFor||state);try{const url=URL.createObjectURL(file);let img;try{img=await loadImage(url)}finally{URL.revokeObjectURL(url)}const c=document.createElement('canvas'),scale=Math.min(1,2000/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const art=await canvasBlob(c,'image/jpeg',.93),preview=await canvasBlob(await draftCanvas(s,600),'image/jpeg',.85);const artworkId=uid();await dbAction('readwrite',store=>store.put({id:artworkId,state:{...s,id:artworkId},title:s.title||file.name.replace(/\.[^.]+$/,''),updated:Date.now(),preview,art}));$('#modal').close();await refreshCount();setView('gallery');toast('成品已收藏，可以分享了。')}catch(err){toast(err.message)}finally{importArtFor=null}});
$('#draft-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>100000)return toast('草稿文件过大，请选择花间导出的 JSON 文件。');try{const next=validate(JSON.parse(await file.text()));checkpoint();state=next;state.id=uid();selected=state.items.at(-1)?.id||null;renderAll();$('#modal').close();setView('studio');toast('草稿已恢复，可以继续创作。')}catch{toast('文件无法读取，请选择花间导出的 composition.json。')}});
icons();renderMaterials();renderAll();refreshCount();if(sharedLoaded)setTimeout(()=>toast('已打开分享草稿，你可以继续创作。'),700);
